/** "이렇게 하세요" illustration of an assessment expression, drawn with the rehab face (full effort, no hands). */
import { useEffect, useState } from 'preact/hooks';
import type { MovementTaskId, Side, TaskId } from '../../core';
import { exerciseById } from '../../rehab/exercises';
import { NEUTRAL, planFor, sceneAt, type Expr } from '../../rehab/motion';
import { render2D } from '../rehab/face2d';

const EXPR: Record<MovementTaskId, Partial<Expr>> = {
  brow: { brow: 1 },
  eyeClose: { eyeClose: 1 },
  // Teeth together, lips parted: the smile is measured with the jaw closed (SRS-QC-009).
  smile: { smile: 1, grin: 1 },
  snarl: { snarl: 1 },
  pucker: { pucker: 1 },
};

let seq = 0;

/** `amount` 0–1 scales the expression (the animated example drives it). */
export function TaskExample({ task, affectedSide, amount = 1 }: { task: TaskId; affectedSide: Side; amount?: number }) {
  const ex = exerciseById('nmr-smile')!;
  const base = sceneAt(ex, 0, planFor(ex));
  const target = task === 'rest' ? {} : EXPR[task];
  const expr = Object.fromEntries(Object.entries(target).map(([k, v]) => [k, (v as number) * amount])) as Partial<Expr>;
  // Show a symmetric healthy face: the patient should try the full movement on both sides.
  const scene = { ...base, muscle: null, keep: null, expr: { ...NEUTRAL, ...expr } };
  const r = render2D(
    scene,
    { affectedSide, mirror: true, showMuscle: false, callouts: false, ghostHands: false, compact: true },
    `tx${++seq}`,
  );
  return <svg class="fsr-svg" viewBox={r.viewBox} dangerouslySetInnerHTML={{ __html: r.svg }} aria-hidden="true" />;
}

const ease = (t: number) => t * t * (3 - 2 * t);

/**
 * The example as a loop, rest → full expression → hold → rest (about 3 s), shown before a retake after a rejected
 * step (SRS-QC-006). With reduced motion asked for, the full expression stands still.
 */
export function TaskExampleAnim({ task, affectedSide }: { task: TaskId; affectedSide: Side }) {
  const still = typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const [k, setK] = useState(still ? 1 : 0);
  useEffect(() => {
    if (still) return undefined;
    let raf = 0;
    let last = 0;
    const t0 = performance.now();
    const loop = (now: number) => {
      if (now - last > 50) {
        last = now;
        const t = ((now - t0) / 1000) % 3;
        setK(t < 0.8 ? ease(t / 0.8) : t < 2 ? 1 : t < 2.6 ? 1 - ease((t - 2) / 0.6) : 0);
      }
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [task, still]);
  return <TaskExample task={task} affectedSide={affectedSide} amount={k} />;
}
